import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.bijRUqYl.js";const d=JSON.parse('{"title":"房产与中介提示词模板","description":"房产中介的 5 条提示词模板：房源描述、带看复盘、客户跟进、小区对比、谈判准备。","frontmatter":{"title":"房产与中介提示词模板","description":"房产中介的 5 条提示词模板：房源描述、带看复盘、客户跟进、小区对比、谈判准备。"},"headers":[],"relativePath":"community/prompts/房产与中介.md","filePath":"community/prompts/房产与中介.md"}'),e={name:"community/prompts/房产与中介.md"};function l(o,s,i,c,r,u){return n(),p("div",null,[...s[0]||(s[0]=[t(`<h1 id="🏠-房产与中介-·-5-条提示词模板" tabindex="-1">🏠 房产与中介 · 5 条提示词模板 <a class="header-anchor" href="#🏠-房产与中介-·-5-条提示词模板" aria-label="Permalink to &quot;🏠 房产与中介 · 5 条提示词模板&quot;">​</a></h1><blockquote><p>这行赚钱靠两件事：<strong>把房子说清楚</strong>，和<strong>把人跟住</strong>。 两件事都靠&quot;信息整理&quot;，而整理正好是 AI 最擅长的。</p></blockquote><h2 id="本行三句话骨架" tabindex="-1">本行三句话骨架 <a class="header-anchor" href="#本行三句话骨架" aria-label="Permalink to &quot;本行三句话骨架&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我手上是【房源情况 / 客户情况】，在【哪个城市哪个板块】。</span></span>
<span class="line"><span>帮我产出【房源文案 / 跟进计划 / 对比表】，形式【…】。</span></span>
<span class="line"><span>按真实数据来，我没给的信息一律标&quot;待确认&quot;，不许替我估算。</span></span></code></pre></div><hr><h2 id="_1-·-房源信息-→-一条有人愿意点进来的房源描述" tabindex="-1">1 · 房源信息 → 一条有人愿意点进来的房源描述 <a class="header-anchor" href="#_1-·-房源信息-→-一条有人愿意点进来的房源描述" aria-label="Permalink to &quot;1 · 房源信息 → 一条有人愿意点进来的房源描述&quot;">​</a></h2><p><strong>什么时候用</strong>：房源信息表里全是&quot;南北通透、采光好、学区房&quot;，发出去没人看。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>房源真实情况：</span></span>
<span class="line"><span>- 小区与位置：【…】</span></span>
<span class="line"><span>- 面积 / 户型 / 楼层 / 朝向 / 装修 / 房龄：【…】</span></span>
<span class="line"><span>- 挂牌价与同小区近期成交价（我有多少写多少）：【…】</span></span>
<span class="line"><span>- 优点（说实话）：【…】</span></span>
<span class="line"><span>- 缺点（必须诚实写，我要提前说清）：【…】</span></span>
<span class="line"><span>目标买家：【首套刚需 / 改善 / 投资 / 学区需求】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我写：</span></span>
<span class="line"><span>① 一个 30 字内的标题</span></span>
<span class="line"><span>② 一段适合朋友圈/微信群发的正文（不超过 200 字）：先写这套房&quot;最适合谁&quot;，再写 3 个具体事实，最后一句行动指引</span></span>
<span class="line"><span>③ 一段适合平台详情页的完整介绍（分：户型亮点 / 生活配套 / 需要注意的地方）</span></span>
<span class="line"><span>④ 3 个买家最可能追问的问题，以及我该怎么答</span></span>
<span class="line"><span>规矩：不许写&quot;绝版&quot;&quot;最后一套&quot;&quot;升值潜力大&quot;；不许编学区、地铁距离、规划消息；不确定的数字标出来。</span></span></code></pre></div><p><strong>它给你</strong>：标题 + 群发文案 + 详情页介绍 + 预判问答。</p><hr><h2 id="_2-·-带看复盘-→-下次带看怎么排" tabindex="-1">2 · 带看复盘 → 下次带看怎么排 <a class="header-anchor" href="#_2-·-带看复盘-→-下次带看怎么排" aria-label="Permalink to &quot;2 · 带看复盘 → 下次带看怎么排&quot;">​</a></h2><p><strong>什么时候用</strong>：一天带看 3 组，回店里全忘了客人当时说了什么、眼神在哪停了一下。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>今天带看的情况：</span></span>
<span class="line"><span>① 客户：【需求 / 预算 / 已看过几套 / 关注点】</span></span>
<span class="line"><span>   带看的房：【…】</span></span>
<span class="line"><span>   客户的真实反应（你观察到的）：【对哪间多看了、说了什么、摇头的是什么】</span></span>
<span class="line"><span>②（依次写）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我：</span></span>
<span class="line"><span>① 把每组客户整理成一张记录卡（需求 / 关注点 / 卡点 / 下一步）</span></span>
<span class="line"><span>② 判断每组客户现在处于什么阶段（只是看看 / 在比对 / 快到决策点 / 可能要流失），并说明依据</span></span>
<span class="line"><span>③ 给每组写一条明天该发的微信（不要催，要给他一个新的&quot;信息增量&quot;）</span></span>
<span class="line"><span>④ 告诉我：哪一组被我高估了，为什么</span></span>
<span class="line"><span>规矩：从我的观察记录推，不许替我加客户的心理活动。</span></span></code></pre></div><p><strong>它给你</strong>：客户记录卡 + 阶段判断 + 明天的跟进微信。<strong>第④条会有点扎心，但是真有用。</strong></p><hr><h2 id="_3-·-客户跟进节奏-不同阶段不同打法" tabindex="-1">3 · 客户跟进节奏（不同阶段不同打法） <a class="header-anchor" href="#_3-·-客户跟进节奏-不同阶段不同打法" aria-label="Permalink to &quot;3 · 客户跟进节奏（不同阶段不同打法）&quot;">​</a></h2><p><strong>什么时候用</strong>：手里几十个客户，靠记忆跟进，总有人跟丢，也总有人被跟烦。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我的客户情况（代号即可）：</span></span>
<span class="line"><span>- 客户 A：【需求 / 上次联系是什么时候 / 聊到什么程度 / 现在卡在哪】</span></span>
<span class="line"><span>- 客户 B：【…】</span></span>
<span class="line"><span>（依次）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我：</span></span>
<span class="line"><span>① 按&quot;温度&quot;把这批客户分成四组：热（一周内可能成交）/ 温（一个月内）/ 冷（观望）/ 暂缓（明确不买）</span></span>
<span class="line"><span>② 给每一组一个跟进节奏（隔多久联系、每次说什么类型的内容、最多跟几次就停）</span></span>
<span class="line"><span>③ 给&quot;温&quot;和&quot;冷&quot;的每一组客户，各写一条具体的联系内容（要带信息增量，不能只是&quot;最近看房了吗&quot;）</span></span>
<span class="line"><span>④ 标出哪些客户我应该主动劝他&quot;再等等&quot;（诚实反而更容易成交）</span></span>
<span class="line"><span>规矩：不许编政策、利率、价格走势；要引用数据必须先让我提供。</span></span></code></pre></div><p><strong>它给你</strong>：分组 + 跟进节奏 + 可直接发的消息。</p><hr><h2 id="_4-·-小区对比表-客户问-这两个小区哪个好" tabindex="-1">4 · 小区对比表（客户问&quot;这两个小区哪个好&quot;） <a class="header-anchor" href="#_4-·-小区对比表-客户问-这两个小区哪个好" aria-label="Permalink to &quot;4 · 小区对比表（客户问&quot;这两个小区哪个好&quot;）&quot;">​</a></h2><p><strong>什么时候用</strong>：客户在 A、B 两个小区之间摇摆，你各说各的好，反而让他更乱。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户：【预算 / 家庭结构 / 通勤地点 / 最在意什么】</span></span>
<span class="line"><span>要对比的小区：</span></span>
<span class="line"><span>- 小区 A：【我掌握的信息：价格区间、房龄、物业、车位、学区、通勤、周边】</span></span>
<span class="line"><span>- 小区 B：【…】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我：</span></span>
<span class="line"><span>① 做一张对比表，维度用&quot;客户在意什么&quot;来定（不要用行业套话维度）</span></span>
<span class="line"><span>② 每个维度给出&quot;对这位客户意味着什么&quot;的一句话解读</span></span>
<span class="line"><span>③ 结论：给这位客户一个明确推荐，并说明&quot;什么情况下我会反过来推荐另一个&quot;</span></span>
<span class="line"><span>④ 列出我还需要核实、不能凭印象回答的信息</span></span>
<span class="line"><span>规矩：不确定的一律写&quot;需核实&quot;；不许编学区划片、地铁规划、物业口碑。</span></span></code></pre></div><p><strong>它给你</strong>：一张能让客户自己看明白的表 + 一个敢下的结论。</p><hr><h2 id="_5-·-谈判前的准备-谈价-谈条件" tabindex="-1">5 · 谈判前的准备（谈价 / 谈条件） <a class="header-anchor" href="#_5-·-谈判前的准备-谈价-谈条件" aria-label="Permalink to &quot;5 · 谈判前的准备（谈价 / 谈条件）&quot;">​</a></h2><p><strong>什么时候用</strong>：明天要坐下来谈，双方差距不小，你怕被带着走。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这次要谈的是：【买方 / 卖方】，标的是【房子基本情况】。</span></span>
<span class="line"><span>双方立场：对方要【…】，我方底线是【…】，目前差距【…】</span></span>
<span class="line"><span>对方的情况：【急不急 / 资金情况 / 有没有其他选择 / 之前谈过什么】</span></span>
<span class="line"><span>我方的筹码：【…】</span></span>
<span class="line"><span>我最怕谈崩的地方：【…】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我准备：</span></span>
<span class="line"><span>① 谈判开场怎么说（30 秒，先定调）</span></span>
<span class="line"><span>② 对方最可能提出的 3 个要求，以及每一句话该怎么接（含&quot;不立刻答应也不直接拒绝&quot;的缓冲话术）</span></span>
<span class="line"><span>③ 我可以用来交换的筹码清单（排序：先让什么、后让什么、什么绝对不让）</span></span>
<span class="line"><span>④ 出现僵局时的两个&quot;换个话题&quot;方案</span></span>
<span class="line"><span>⑤ 什么情况下我该主动暂停、下次再谈</span></span>
<span class="line"><span>规矩：所有数字只能来自我给的；不许替我假设对方心理；给我可执行的句子，不要空泛原则。</span></span></code></pre></div><p><strong>它给你</strong>：一份可以直接带去谈的准备稿。<strong>&quot;什么情况下暂停&quot;这一条，能救回不少单子。</strong></p><hr><h2 id="⚠️-这行的三条红线" tabindex="-1">⚠️ 这行的三条红线 <a class="header-anchor" href="#⚠️-这行的三条红线" aria-label="Permalink to &quot;⚠️ 这行的三条红线&quot;">​</a></h2><ol><li><strong>学区、规划、政策不许编</strong>：这几样是中介纠纷高发区，AI 说的不算，文件说了才算。凡是要对客户说出口，先找官方口径。</li><li><strong>产权、查封、抵押情况必须自己核</strong>：这类信息不能靠 AI 推断，也不能靠印象。</li><li><strong>客户隐私别外传</strong>：客户名单、电话、成交价，给 AI 处理前先脱敏成代号。</li></ol><hr><p><strong>目录</strong>：<a href="/MoMAWork-/community/prompts/">← 回到行业提示词模板库</a> ｜ 下一个行业 → <strong><a href="/MoMAWork-/community/prompts/医疗健康.html">医疗健康与药店</a></strong></p>`,34)])])}const g=a(e,[["render",l]]);export{d as __pageData,g as default};
